def tokenize(str)
  tokens = []
  @skipped = []
  scanner = StringScanner.new(str)
  until scanner.eos?
    if (word = scanner.scan(Kanbun::Lexicon::PATTERN))
      tokens << [Kanbun::Lexicon.token_for(word, scanner), word]
    elsif scanner.scan(Kanbun::Lexicon::PUNCTUATION)
      next
    else
      @skipped << scanner.getch
    end
  end
  tokens << [false, nil]
  tokens
end

